import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.*;

public class Main {
    public static void main(String[] args) throws IOException {
        File file = new File("todo-perintah.json");
        Files.deleteIfExists(file.toPath());
        TodoService service = new TodoService(new TodoRepositoryJson(file));
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(" ", 2);
            if (d[0].equals("tambah")) {
                service.tambah(d[1]);
            } else if (d[0].equals("selesai")) {
                service.selesaikan(Integer.parseInt(d[1]));
            }
        }
        for (Todo t : new TodoService(new TodoRepositoryJson(file)).semua()) {
            System.out.println(t);
        }
    }
}

class Todo {
    private final int id;
    private final String judul;
    private boolean selesai;

    @JsonCreator
    Todo(@JsonProperty("id") int id, @JsonProperty("judul") String judul, @JsonProperty("selesai") boolean selesai) {
        this.id = id;
        this.judul = judul;
        this.selesai = selesai;
    }

    public int getId() {
        return id;
    }

    public String getJudul() {
        return judul;
    }

    public boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

interface TodoRepository {
    Todo simpan(String judul);

    List<Todo> semua();

    Todo cari(int id);

    boolean hapus(int id);

    void perbarui(Todo todo);
}

class TodoRepositoryJson implements TodoRepository {
    private final ObjectMapper mapper = new ObjectMapper();
    private final File file;
    private final List<Todo> data;

    TodoRepositoryJson(File file) {
        this.file = file;
        this.data = baca();
    }

    private List<Todo> baca() {
        if (!file.exists()) {
            return new ArrayList<>();
        }
        try {
            return mapper.readValue(file, new TypeReference<List<Todo>>() {});
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void tulis() {
        try {
            mapper.writerWithDefaultPrettyPrinter().writeValue(file, data);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    public Todo simpan(String judul) {
        int id = 1;
        for (Todo t : data) {
            id = Math.max(id, t.getId() + 1);
        }
        Todo t = new Todo(id, judul, false);
        data.add(t);
        tulis();
        return t;
    }

    public List<Todo> semua() {
        return new ArrayList<>(data);
    }

    public Todo cari(int id) {
        for (Todo t : data) {
            if (t.getId() == id) {
                return t;
            }
        }
        return null;
    }

    public boolean hapus(int id) {
        Todo t = cari(id);
        if (t == null) {
            return false;
        }
        data.remove(t);
        tulis();
        return true;
    }

    public void perbarui(Todo todo) {
        tulis();
    }
}

class TodoTidakDitemukanException extends RuntimeException {
    TodoTidakDitemukanException(int id) {
        super("Todo nomor " + id + " tidak ditemukan");
    }
}

class TodoService {
    private final TodoRepository repo;

    TodoService(TodoRepository repo) {
        this.repo = repo;
    }

    Todo tambah(String judul) {
        if (judul == null || judul.trim().isEmpty()) {
            throw new IllegalArgumentException("Judul tidak boleh kosong");
        }
        if (judul.trim().length() > 50) {
            throw new IllegalArgumentException("Judul maksimal 50 huruf");
        }
        return repo.simpan(judul.trim());
    }

    void selesaikan(int id) {
        Todo t = repo.cari(id);
        if (t == null) {
            throw new TodoTidakDitemukanException(id);
        }
        t.selesaikan();
        repo.perbarui(t);
    }

    void hapus(int id) {
        if (!repo.hapus(id)) {
            throw new TodoTidakDitemukanException(id);
        }
    }

    List<Todo> semua() {
        return repo.semua();
    }
}
